"""Identity has to be checked when a delta is expected, too (checkpoint B1). No Docker.

The identity comparison used to sit inside `if not want:`, so it ran for `expect_delta={}` and
for nothing else — which is to say it ran for no create and no delete. Both snapshots collected
the per-namespace `(gramps_id, handle)` sets and threw them away, and `GuardedWrite` narrowed
them to `["counts"]` on the way out, so the caller could not diff them either.

What that let through is not exotic. A `delete_person` whose query filter is gone deletes
`people[0]`; the count moves by exactly the -1 the test expected, `gramps_id` in the report is
the echo of the argument and `deleted: True` is a literal, so every check in the suite agreed
while the named person was still in the tree. This file is that scenario and its three
siblings, plus the guards against the fix over-reaching.
"""

from __future__ import annotations

from typing import Any

import pytest
from harness.assertions import assert_guarded_write, payload
from harness.docker_util import ProbeError
from harness.movement import EVERYTHING, movement_of
from stubs.fake_identity import FIRST_PERSON, RENUMBERED, FakeIdentityMcp
from stubs.fake_tree import FakeRest, FakeTree

SUBJECT = "I0002"
NEW_PERSON = "I0003"


@pytest.fixture
def tree() -> FakeTree:
    return FakeTree()


@pytest.fixture
def rest(tree: FakeTree) -> FakeRest:
    return FakeRest(tree)


@pytest.fixture
def mcp(tree: FakeTree) -> FakeIdentityMcp:
    return FakeIdentityMcp(tree)


def delete(rest: FakeRest, mcp: FakeIdentityMcp, **kwargs: Any) -> Any:
    return assert_guarded_write(
        rest,
        mcp,
        "gramps_delete_person",
        {"gramps_id": SUBJECT, "confirm": True},
        expect_delta={"people": -1},
        self_report="delete",
        **kwargs,
    )


def add(rest: FakeRest, mcp: FakeIdentityMcp, **kwargs: Any) -> Any:
    return assert_guarded_write(
        rest,
        mcp,
        "gramps_add_person",
        {"first_name": "Neu", "surname": "Brehmer"},
        expect_delta={"people": 1},
        self_report="id",
        id_namespace="people",
        **kwargs,
    )


def import_file(rest: FakeRest, mcp: FakeIdentityMcp, **kwargs: Any) -> Any:
    return assert_guarded_write(
        rest,
        mcp,
        "gramps_import_file",
        {"filename": "synthetic-tree.gramps"},
        expect_delta={"people": 1},
        self_report="counts",
        **kwargs,
    )


# -- what a counts-only guard cannot see ----------------------------------------------


def test_a_delete_that_removes_the_wrong_person_is_caught(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    """The headline scenario. One person fewer is exactly what the test asked for; the person
    who left is not the one it named."""
    mcp.delete_wrong_person = True

    with pytest.raises(AssertionError, match=FIRST_PERSON):
        delete(rest, mcp, expect_removed={"people": [SUBJECT]})


def test_the_report_of_that_same_delete_is_word_for_word_correct(mcp: FakeIdentityMcp) -> None:
    """Why the tree has to be asked. Nothing in this report is false, and `_assert_delete`
    compares it only against itself — the product raises on that arithmetic anyway."""
    mcp.delete_wrong_person = True

    reported = payload(mcp.call("gramps_delete_person", {"gramps_id": SUBJECT, "confirm": True}))

    assert reported == {
        "gramps_id": SUBJECT,
        "deleted": True,
        "count_before": 3,
        "count_after": 2,
    }
    assert SUBJECT in mcp.tree.namespaces["people"], "premise: the named person never left"


def test_a_create_that_hands_back_an_id_that_already_existed_is_caught(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    """`assert_new_id_resolves` looks the id up, and an id that was already there resolves.
    Only "did *this* call put it there" separates the two."""
    mcp.stale_id = True

    with pytest.raises(AssertionError, match=FIRST_PERSON):
        add(rest, mcp)


def test_an_identity_swap_beside_an_expected_delta_is_caught(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    """The swap the suite already catches for `expect_delta={}` — invisible the moment any
    other namespace is expected to move."""
    mcp.swap_family = True

    with pytest.raises(AssertionError, match="identity"):
        import_file(rest, mcp)


def test_a_gramps_id_edited_under_a_stable_handle_is_caught(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    """No handle enters or leaves, so a set difference over handles alone sees nothing — and
    every later step of a use case keys off the id, not the handle."""
    mcp.renumber = True

    with pytest.raises(AssertionError, match=RENUMBERED):
        import_file(rest, mcp)


# -- the usage gate: a loss has to be named, before the call goes out -------------------


def test_a_negative_delta_without_a_named_removal_is_refused(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    """Not an assertion failure — a usage error, like the D16 gate. "Something vanished" is
    satisfied by the wrong thing vanishing, so it may not be an expressible expectation."""
    with pytest.raises(ProbeError, match="expect_removed"):
        delete(rest, mcp)


def test_that_gate_fires_before_the_destructive_call_goes_out(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    """A gate that raises after the fact still deleted a person. The expectation is fully
    known before the call, so the refusal belongs there."""
    with pytest.raises(ProbeError):
        delete(rest, mcp)

    assert mcp.calls == [], "the call went out despite the usage error"
    assert SUBJECT in mcp.tree.namespaces["people"]


def test_a_named_removal_that_names_nothing_is_refused(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    """The B2 lesson applied to this parameter: present is not the same as covering."""
    with pytest.raises(ProbeError, match="expect_removed"):
        delete(rest, mcp, expect_removed={"people": []})


# -- exactness ------------------------------------------------------------------------


def test_a_declared_removal_the_tree_does_not_confirm_is_caught(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    """The honest tool, the wrong declaration — the comparison has to run both ways."""
    with pytest.raises(AssertionError, match="I0001"):
        delete(rest, mcp, expect_removed={"people": ["I0001"]})


def test_everything_means_everything_and_not_anything(rest: FakeRest, mcp: FakeIdentityMcp) -> None:
    """`EVERYTHING` is shorthand for "the ids this namespace held", not a wildcard: used for a
    single delete it over-claims, and says so."""
    with pytest.raises(AssertionError, match=FIRST_PERSON):
        delete(rest, mcp, expect_removed={"people": EVERYTHING})


def test_naming_one_side_of_a_namespace_names_both(rest: FakeRest, mcp: FakeIdentityMcp) -> None:
    """A declaration is not a partial waiver. `replace_person` really does remove the named
    person, so the half that was declared is satisfied — and the person it creates in the same
    breath goes unremarked unless the undeclared half is held to "nothing"."""
    with pytest.raises(AssertionError, match=NEW_PERSON):
        assert_guarded_write(
            rest,
            mcp,
            "gramps_replace_person",
            {"gramps_id": SUBJECT},
            expect_delta={},
            self_report="unguarded",
            expect_removed={"people": [SUBJECT]},
        )


# -- the guards against over-reach -----------------------------------------------------


def test_an_honest_delete_that_names_what_vanished_passes(
    rest: FakeRest, mcp: FakeIdentityMcp
) -> None:
    written = delete(rest, mcp, expect_removed={"people": [SUBJECT]})

    assert written.removed == {"people": [SUBJECT]}
    assert written.added == {}


def test_an_honest_create_needs_no_declaration(rest: FakeRest, mcp: FakeIdentityMcp) -> None:
    """A server-assigned id cannot be named in advance, so a create is held to "exactly one
    appeared, none left" — and to the reported id being the one that appeared."""
    written = add(rest, mcp)

    assert written.added == {"people": [NEW_PERSON]}
    assert written.payload == NEW_PERSON


def test_a_declared_churn_is_allowed(rest: FakeRest, mcp: FakeIdentityMcp) -> None:
    """One out, one in, every count where it started — legal exactly when the test says both
    halves out loud. Undeclared, this is the swap `test_00_assertions.py` already catches."""
    written = assert_guarded_write(
        rest,
        mcp,
        "gramps_replace_person",
        {"gramps_id": SUBJECT},
        expect_delta={},
        self_report="unguarded",
        expect_removed={"people": [SUBJECT]},
        expect_added={"people": [NEW_PERSON]},
    )

    assert written.delta == {}


def test_a_wipe_may_declare_everything_it_removed(rest: FakeRest, mcp: FakeIdentityMcp) -> None:
    """The escape hatch that makes the rule livable: naming every id of a 391-object tree is
    not an expectation anyone writes, and "all of them" is checkable."""
    total = sum(mcp.tree.counts().values())

    written = assert_guarded_write(
        rest,
        mcp,
        "gramps_delete_all_objects",
        {"confirm": True, "expected_count": total},
        expect_delta={"people": -3, "families": -1},
        self_report="counts",
        expect_removed={"people": EVERYTHING, "families": EVERYTHING},
    )

    assert written.after == {"people": 0, "families": 0, "notes": 0, "tags": 0}


# -- the identity projection itself ----------------------------------------------------


def test_an_object_without_a_gramps_id_is_named_by_its_handle() -> None:
    """Tags carry no `gramps_id` (`/api/tags/`), so projecting on it alone would make every
    tag the same object and a swap of two of them unreportable."""
    before = {"counts": {"tags": 1}, "objects": {"tags": [("", "h-a")]}}
    after = {"counts": {"tags": 1}, "objects": {"tags": [("", "h-b")]}}

    moved = movement_of(before, after)

    assert moved.removed == {"tags": ["handle:h-a"]}
    assert moved.added == {"tags": ["handle:h-b"]}
